import React from 'react';

import { cn } from '../utils/cn';

export interface ArmTakeProps {
  className?: string;
  disabled?: boolean;
  /** How long a hold takes to confirm. */
  holdMs?: number;
  label: string;
  /** Called when the take is confirmed: a hold of `holdMs`, or a second press while armed. */
  onTake: () => void;
  /** How long an armed control waits for the second press before it disarms itself. */
  armTimeoutMs?: number;
}

function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined' && typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

/**
 * A control that cannot fire by accident: hold it for `holdMs` (a fill shows the progress), or
 * press it twice (the first press arms it, the second takes). A single click never takes. With
 * reduced motion there is no fill and no hold, only the two presses. Esc disarms.
 */
export function ArmTake({ armTimeoutMs = 5_000, className, disabled = false, holdMs = 800, label, onTake }: ArmTakeProps) {
  const [armed, setArmed] = React.useState(false);
  const [progress, setProgress] = React.useState(0);
  const frame = React.useRef<number | null>(null);
  const startedAt = React.useRef<number | null>(null);
  // The click that follows a completed hold must not arm the control again.
  const heldConfirmed = React.useRef(false);
  const armTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const take = React.useRef(onTake);
  take.current = onTake;

  const clearTimer = React.useCallback(() => {
    if (armTimer.current) clearTimeout(armTimer.current);
    armTimer.current = null;
  }, []);

  const disarm = React.useCallback(() => {
    clearTimer();
    setArmed(false);
  }, [clearTimer]);

  const stopHold = React.useCallback(() => {
    if (frame.current !== null) cancelAnimationFrame(frame.current);
    frame.current = null;
    startedAt.current = null;
    setProgress(0);
  }, []);

  const confirm = React.useCallback(() => {
    clearTimer();
    setArmed(false);
    take.current();
  }, [clearTimer]);

  const arm = React.useCallback(() => {
    clearTimer();
    setArmed(true);
    armTimer.current = setTimeout(() => setArmed(false), armTimeoutMs);
  }, [armTimeoutMs, clearTimer]);

  React.useEffect(
    () => () => {
      clearTimer();
      if (frame.current !== null) cancelAnimationFrame(frame.current);
    },
    [clearTimer]
  );

  const tick = React.useCallback(
    (now: number) => {
      if (startedAt.current === null) return;
      const ratio = Math.min(1, (now - startedAt.current) / holdMs);
      setProgress(ratio);
      if (ratio >= 1) {
        frame.current = null;
        startedAt.current = null;
        setProgress(0);
        heldConfirmed.current = true;
        confirm();
        return;
      }
      frame.current = requestAnimationFrame(tick);
    },
    [confirm, holdMs]
  );

  const onPointerDown = () => {
    if (disabled || prefersReducedMotion() || startedAt.current !== null) return;
    startedAt.current = performance.now();
    frame.current = requestAnimationFrame(tick);
  };

  const onClick = () => {
    if (heldConfirmed.current) {
      heldConfirmed.current = false;
      return;
    }
    if (armed) confirm();
    else arm();
  };

  return (
    <button
      type='button'
      disabled={disabled}
      aria-label={armed ? `${label}: armed, press again to take` : label}
      data-armed={armed}
      onPointerDown={onPointerDown}
      onPointerUp={stopHold}
      onPointerLeave={stopHold}
      onPointerCancel={stopHold}
      onBlur={() => {
        stopHold();
        disarm();
      }}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && armed) {
          event.preventDefault();
          disarm();
        }
      }}
      onClick={onClick}
      className={cn(
        'relative inline-flex h-9 select-none items-center gap-2 overflow-hidden rounded-[var(--radius-button)] border px-4 text-xs font-bold uppercase tracking-wider focus:outline-none focus-visible:ring-2 focus-visible:ring-sea disabled:pointer-events-none disabled:opacity-50 dark:focus-visible:ring-accent-blue',
        armed ? 'border-accent-red bg-accent-red text-white' : 'border-accent-text text-accent-text dark:border-accent-yellow dark:text-accent-yellow',
        className
      )}
    >
      <span aria-hidden='true' data-arm-fill className='absolute inset-y-0 left-0 bg-accent-red/70' style={{ width: `${progress * 100}%` }} />
      <span className='relative'>{armed ? 'Press again to take' : label}</span>
      <span role='status' className='sr-only'>
        {armed ? 'Armed. Press again within the time shown to take.' : ''}
      </span>
    </button>
  );
}

import React from 'react';

import { cn } from '../utils/cn';

export interface KeyCapProps extends React.HTMLAttributes<HTMLElement> {
  /** One cap per key, for a chord: `keys={['⌘', 'K']}`. */
  keys?: string[];
}

const capClasses =
  'inline-flex h-5 min-w-5 items-center justify-center rounded-[5px] border border-b-2 border-sand/60 bg-white px-1.5 font-mono text-[11px] font-semibold text-text-secondary dark:border-white/20 dark:bg-deep-sea/60 dark:text-text-primary';

/** A keyboard key as a cap with a heavier bottom edge. Kbd stays exported; KeyCap is the new styling. */
export function KeyCap({ className, children, keys, ...props }: KeyCapProps) {
  if (keys && keys.length > 0) {
    return (
      <span className='inline-flex items-center gap-1' role='group' aria-label={keys.join(' ')}>
        {keys.map((key, index) => (
          <kbd key={`${key}-${index}`} {...props} className={cn(capClasses, className)}>
            {key}
          </kbd>
        ))}
      </span>
    );
  }
  return (
    <kbd {...props} className={cn(capClasses, className)}>
      {children}
    </kbd>
  );
}

import { cn } from '../utils/cn';

export interface MeterProps {
  className?: string;
  /** The held maximum, in the same scale as `value`. */
  hold?: number | null;
  label: string;
  max: number;
  min: number;
  /** The live peak, in the same scale as `value`. */
  peak?: number | null;
  unit?: string;
  value: number | null;
  /** From here to `max` the scale is the warning zone, and a hold inside it turns red. */
  warnFrom?: number;
}

/**
 * A reading and its scale: a level between `min` and `max` with an optional live peak, a held peak
 * and a warning zone. It does not animate; the page feeds it new values.
 */
export function Meter({ className, hold, label, max, min, peak, unit, value, warnFrom }: MeterProps) {
  const span = max - min;
  const at = (reading: number) => (span > 0 ? Math.max(0, Math.min(100, ((reading - min) / span) * 100)) : 0);
  return (
    <div
      role='meter'
      aria-label={label}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value ?? min}
      aria-valuetext={value === null ? 'No level' : `${value.toFixed(1)}${unit ? ` ${unit}` : ''}`}
      className={cn('relative h-1.5 overflow-hidden rounded-full bg-sand/30 dark:bg-sand/25', className)}
    >
      {warnFrom !== undefined ? <span data-meter='warn' className='absolute inset-y-0 right-0 bg-terracotta/35' style={{ left: `${at(warnFrom)}%` }} /> : null}
      {value !== null ? <span data-meter='fill' className='absolute inset-y-0 left-0 bg-sea dark:bg-accent-blue' style={{ width: `${at(value)}%` }} /> : null}
      {peak !== undefined && peak !== null ? <span data-meter='peak' className='absolute inset-y-0 w-0.5 bg-text-primary/80' style={{ left: `calc(${at(peak)}% - 1px)` }} /> : null}
      {hold !== undefined && hold !== null ? (
        <span
          data-meter='hold'
          className={cn('absolute inset-y-0 w-0.5', warnFrom !== undefined && hold >= warnFrom ? 'bg-terracotta' : 'bg-accent-text dark:bg-accent-yellow')}
          style={{ left: `calc(${at(hold)}% - 1px)` }}
        />
      ) : null}
    </div>
  );
}

import React from 'react';

import { cn } from '../utils/cn';
import { StatePill, type StatePillProps, type StatePillTone } from './state-pill';

export type OnAirState = 'live' | 'armed' | 'idle';

export interface OnAirStripPill {
  label: string;
  title?: string;
  tone: StatePillTone;
}

export interface OnAirStripProps {
  className?: string;
  /** A clock or any trailing readout, shown at the right. */
  clock?: React.ReactNode;
  /** What plays now: a title line and a detail line. */
  now?: { detail?: string; title: string };
  /** What plays next. */
  next?: { detail?: string; title: string };
  /** Health chips: stream, engine, monitor. */
  pills?: OnAirStripPill[];
  state: OnAirState;
  /** What the state says when it differs from its default words (On air, Armed, Off air). */
  stateLabel?: string;
  /** Shown when nothing is on air. */
  idleText?: string;
}

const STATE_TONES: Record<OnAirState, { label: string; tone: StatePillProps['tone'] }> = {
  live: { label: 'On air', tone: 'live' },
  armed: { label: 'Armed', tone: 'arm' },
  idle: { label: 'Off air', tone: 'idle' }
};

/**
 * A one-row strip for the top of a console: whether the program is on air, what plays and what is
 * next, the health chips and a clock. Tones come from StatePill.
 */
export function OnAirStrip({ className, clock, idleText = 'Nothing on air', next, now, pills = [], state, stateLabel }: OnAirStripProps) {
  const base = STATE_TONES[state];
  return (
    <section aria-label='On air' data-state={state} className={cn('flex flex-wrap items-center gap-x-5 gap-y-2 rounded-[var(--radius-card)] bg-deep-sea px-4 py-2.5 text-white', className)}>
      <StatePill tone={base.tone} label={stateLabel ?? base.label} pulse={state === 'live'} className='border-white/30' />
      <div className='min-w-0 flex-1 basis-56'>
        {now ? (
          <>
            <p className='truncate text-sm font-semibold'>{now.title}</p>
            {now.detail ? <p className='truncate text-xs text-white/70'>{now.detail}</p> : null}
          </>
        ) : (
          <p className='text-sm text-white/70'>{idleText}</p>
        )}
      </div>
      {next ? (
        <div className='min-w-0 basis-48 text-xs'>
          <p className='text-white/70'>Next</p>
          <p className='truncate'>
            <span className='font-semibold'>{next.title}</span>
            {next.detail ? <span className='text-white/70'> · {next.detail}</span> : null}
          </p>
        </div>
      ) : null}
      {pills.length > 0 ? (
        <div className='flex flex-wrap items-center gap-1.5'>
          {pills.map((pill) => (
            <StatePill key={pill.label} tone={pill.tone} label={pill.label} title={pill.title} />
          ))}
        </div>
      ) : null}
      {clock ? <div className='font-mono text-lg font-semibold tabular-nums'>{clock}</div> : null}
    </section>
  );
}

import { cn } from '../utils/cn';
import { ToggleGroup, ToggleGroupItem } from './toggle-group';

export interface SegmentedFilterOption {
  /** Shown after the label, in tabular numerals. */
  count?: number;
  label: string;
  value: string;
}

export interface SegmentedFilterProps {
  className?: string;
  /** Names the group for assistive technology. */
  label: string;
  onChange: (value: string) => void;
  options: SegmentedFilterOption[];
  value: string;
}

/**
 * One choice of several, always one chosen: a segmented filter built on ToggleGroup. Pressing the
 * chosen segment again keeps it chosen (a filter has no "none").
 */
export function SegmentedFilter({ className, label, onChange, options, value }: SegmentedFilterProps) {
  return (
    <div role='group' aria-label={label} className={cn('inline-flex', className)}>
      <ToggleGroup
        type='single'
        value={value}
        onValueChange={(next) => {
          if (next) onChange(next);
        }}
        size='sm'
      >
        {options.map((option) => (
          <ToggleGroupItem key={option.value} value={option.value}>
            {option.label}
            {option.count !== undefined ? <span className='font-mono text-[11px] tabular-nums text-text-secondary'>{option.count}</span> : null}
          </ToggleGroupItem>
        ))}
      </ToggleGroup>
    </div>
  );
}

import { cn } from '../utils/cn';

export type StatePillTone = 'live' | 'ok' | 'warn' | 'bad' | 'arm' | 'info' | 'idle';

export interface StatePillProps {
  className?: string;
  /** The state, in words. Colour alone never carries it. */
  label: string;
  /** Pulses the dot (a live state). Respects reduced motion. */
  pulse?: boolean;
  title?: string;
  tone: StatePillTone;
}

const toneClasses: Record<StatePillTone, string> = {
  live: 'border-accent-red bg-accent-red text-white',
  ok: 'border-emerald-600/30 bg-emerald-600/[0.08] text-emerald-700 dark:border-emerald-400/35 dark:bg-emerald-400/10 dark:text-emerald-300',
  warn: 'border-desert/35 bg-desert/10 text-accent-text dark:border-desert/35 dark:bg-desert/10 dark:text-accent-text',
  bad: 'border-terracotta/40 bg-terracotta/10 text-[color-mix(in_srgb,var(--color-terracotta),var(--color-text-primary)_35%)] dark:border-terracotta/40 dark:bg-terracotta/10 dark:text-terracotta',
  arm: 'border-accent-text bg-transparent text-accent-text dark:border-accent-yellow dark:text-accent-yellow',
  info: 'border-sea/30 bg-sea/10 text-sea dark:border-accent-blue/35 dark:bg-accent-blue/10 dark:text-accent-blue',
  idle: 'border-sand/40 bg-transparent text-text-secondary dark:border-sand/40 dark:text-text-secondary'
};

/**
 * A state as a dot and a label: the compact status of a row, a strip or a header. StatusBadge stays
 * exported with its current variants; StatePill is its successor with the tones of the console's
 * dense surfaces (on air, ready, measuring, failed, armed).
 */
export function StatePill({ className, label, pulse = false, title, tone }: StatePillProps) {
  return (
    <span
      data-tone={tone}
      title={title}
      className={cn(
        'inline-flex h-[22px] items-center gap-1.5 whitespace-nowrap rounded-full border px-2.5 text-[11px] font-semibold tracking-ui',
        toneClasses[tone],
        className
      )}
    >
      <i aria-hidden='true' className={cn('h-1.5 w-1.5 rounded-full bg-current', pulse && 'motion-safe:animate-pulse')} />
      {label}
    </span>
  );
}

import { Pause, Play, SkipBack, SkipForward } from 'lucide-react';
import React from 'react';

import { cn } from '../utils/cn';

export interface TransportCue {
  /** Where the cue sits, in seconds. */
  at: number;
  label: string;
}

export interface TransportProps {
  className?: string;
  /** Marks on the timeline, such as a song's cue in and cue out. */
  cues?: TransportCue[];
  disabled?: boolean;
  /** Seconds, or null when the length is unknown (the timeline is then hidden). */
  duration: number | null;
  onNext?: () => void;
  onPrev?: () => void;
  /** Called with the new position in seconds. Without it the timeline is read only. */
  onSeek?: (seconds: number) => void;
  onToggle: () => void;
  playing: boolean;
  /** Seconds. */
  position: number;
  subtitle?: string;
  title: string;
}

const SEEK_STEP_SECONDS = 5;

function formatClock(seconds: number | null): string {
  if (seconds === null || !Number.isFinite(seconds)) return '—';
  const whole = Math.max(0, Math.floor(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, '0')}`;
}

/**
 * One shared transport for a list of audio: previous, play or pause, next, what is loaded, a
 * timeline with cue marks, and the time. It is presentational: the page owns the audio element.
 * Space toggles on the timeline, and the arrow keys seek by five seconds.
 */
export function Transport({ className, cues = [], disabled = false, duration, onNext, onPrev, onSeek, onToggle, playing, position, subtitle, title }: TransportProps) {
  const timeline = React.useRef<HTMLDivElement>(null);
  const length = duration !== null && duration > 0 ? duration : null;
  const clamped = length === null ? Math.max(0, position) : Math.min(Math.max(0, position), length);
  const percent = (seconds: number, total: number) => Math.max(0, Math.min(100, (seconds / total) * 100));

  const seekTo = (seconds: number) => {
    if (!onSeek || length === null) return;
    onSeek(Math.max(0, Math.min(length, seconds)));
  };

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (disabled) return;
    if (event.key === ' ') {
      event.preventDefault();
      onToggle();
    } else if (event.key === 'ArrowRight') {
      event.preventDefault();
      seekTo(clamped + SEEK_STEP_SECONDS);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      seekTo(clamped - SEEK_STEP_SECONDS);
    } else if (event.key === 'Home') {
      event.preventDefault();
      seekTo(0);
    } else if (event.key === 'End' && length !== null) {
      event.preventDefault();
      seekTo(length);
    }
  };

  const buttonClass =
    'inline-flex h-8 w-8 items-center justify-center rounded-full text-text-secondary hover:bg-sand/20 hover:text-text-primary focus:outline-none focus-visible:ring-2 focus-visible:ring-sea disabled:pointer-events-none disabled:opacity-40 dark:focus-visible:ring-accent-blue';

  return (
    <div role='group' aria-label='Transport' className={cn('flex items-center gap-4 rounded-[var(--radius-card)] border border-sand/30 bg-light-sand/50 px-4 py-2.5 dark:border-white/10 dark:bg-white/[0.04]', className)}>
      <div className='flex items-center gap-1'>
        <button type='button' aria-label='Previous' className={buttonClass} disabled={disabled || !onPrev} onClick={onPrev}>
          <SkipBack size={14} aria-hidden='true' />
        </button>
        <button
          type='button'
          aria-label={playing ? 'Pause' : 'Play'}
          className='inline-flex h-9 w-9 items-center justify-center rounded-full bg-sea text-white hover:bg-deep-sea focus:outline-none focus-visible:ring-2 focus-visible:ring-sea focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-40 dark:bg-accent-blue dark:hover:bg-accent-blue/80 dark:focus-visible:ring-accent-blue'
          disabled={disabled}
          onClick={onToggle}
        >
          {playing ? <Pause size={16} aria-hidden='true' /> : <Play size={16} aria-hidden='true' />}
        </button>
        <button type='button' aria-label='Next' className={buttonClass} disabled={disabled || !onNext} onClick={onNext}>
          <SkipForward size={14} aria-hidden='true' />
        </button>
      </div>
      <div className='min-w-0 basis-40'>
        <p className='truncate text-sm font-semibold text-text-primary'>{title}</p>
        {subtitle ? <p className='truncate text-[11px] text-text-secondary'>{subtitle}</p> : null}
      </div>
      {length !== null ? (
        <div
          ref={timeline}
          role='slider'
          tabIndex={disabled ? -1 : 0}
          aria-label='Position'
          aria-valuemin={0}
          aria-valuemax={Math.round(length)}
          aria-valuenow={Math.round(clamped)}
          aria-valuetext={`${formatClock(clamped)} of ${formatClock(length)}`}
          aria-disabled={disabled || !onSeek}
          onKeyDown={onKeyDown}
          onClick={(event) => {
            if (!onSeek || disabled || !timeline.current) return;
            const box = timeline.current.getBoundingClientRect();
            if (box.width > 0) seekTo(((event.clientX - box.left) / box.width) * length);
          }}
          className='relative h-4 min-w-24 flex-1 cursor-pointer focus:outline-none focus-visible:ring-2 focus-visible:ring-sea dark:focus-visible:ring-accent-blue'
        >
          <span className='absolute inset-x-0 top-1/2 h-[3px] -translate-y-1/2 rounded-full bg-sand/50 dark:bg-sand/40' />
          <span data-transport='done' className='absolute left-0 top-1/2 h-[3px] -translate-y-1/2 rounded-full bg-sea dark:bg-accent-blue' style={{ width: `${percent(clamped, length)}%` }} />
          {cues.map((cue) => (
            <span key={`${cue.label}-${cue.at}`} data-transport='cue' title={cue.label} className='absolute top-0 h-full w-0.5 bg-accent-text dark:bg-accent-yellow' style={{ left: `${percent(cue.at, length)}%` }} />
          ))}
        </div>
      ) : (
        <div className='flex-1' />
      )}
      <p className='shrink-0 font-mono text-xs tabular-nums text-text-secondary'>
        <b className='text-text-primary'>{formatClock(clamped)}</b> / {formatClock(length)}
      </p>
    </div>
  );
}

